contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint d1, uint d2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d1) + (d2)); require(d1 <= 1000000000000000000000000000000); require(d2 <= 1000000000000000000000000000000);
        require(d1 > 0 && d2 > 0);
        require(address(this).balance >= d1 + d2);

        c.deposit{value: d1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: d2}(); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        uint creditBefore = d1 + d2;
        bool enough = creditBefore <= cBalBefore;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint cBalAfter = address(c).balance;

        assert(
            (reverted && !enough && cBalAfter == cBalBefore)
            ||
            (!reverted && enough && cBalBefore - cBalAfter == creditBefore)
        );
    }

    receive() external payable {}
}

